code.text:
kubectl create serviceaccount reader -n ch10
TOKEN=$(kubectl create token reader -n ch10 --duration=1h)
echo ${#TOKEN}
kubectl config view --raw --minify -o jsonpath='{.clusters[0].cluster.certificate-authority-data}' | base64 -d > ca.crt
kr() { kubectl --kubeconfig=/dev/null --server=https://127.0.0.1:6443 --certificate-authority=$HOME/ch10/ca.crt --token="$TOKEN" "$@"; }
kr auth whoami

